<?php $staff = $data['staff']; $root = $staff ? '/dashboard/admin/training/requests' : '/dashboard/school/training'; $filters = $data['filters']; $rows = $data['rows']; ?>
<section class="page-band"><div class="site-shell"><h1><?= $escape($data['title']) ?></h1><nav class="d-flex gap-3 flex-wrap" aria-label="Training navigation"><a href="/training-workshops">Training catalogue</a><?php if ($staff): ?><a href="/dashboard/admin/training">Manage catalogue</a><a href="/dashboard/admin">Admin dashboard</a><?php else: ?><a href="<?= $root ?>?new=1">Request training</a><a href="/dashboard/school">School dashboard</a><?php endif; ?></nav></div></section>
<div class="site-shell section-space"><?php if ($data['notice'] !== ''): ?><p class="auth-notice" role="status"><?= $escape($data['notice']) ?></p><?php endif; ?>
<?php if ($staff): ?><form method="get" action="<?= $root ?>" class="form-panel mb-4"><div class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label" for="training-filter-q">Search reference or school</label><input class="form-control" id="training-filter-q" name="q" value="<?= $escape($filters['q']) ?>" maxlength="200"></div><div class="col-md-3"><label class="form-label" for="training-filter-status">Status</label><select class="form-select" id="training-filter-status" name="status"><option value="">All statuses</option><?php foreach (['submitted', 'under_review', 'discussion', 'scheduled', 'completed', 'cancelled'] as $status): ?><option value="<?= $status ?>"<?= $filters['status'] === $status ? ' selected' : '' ?>><?= $escape(ucfirst(str_replace('_', ' ', $status))) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label" for="training-filter-admin">Assigned staff</label><select class="form-select" id="training-filter-admin" name="assigned_admin_id"><option value="">All staff</option><?php foreach ($data['admins'] as $admin): ?><option value="<?= (int) $admin['id'] ?>"<?= $filters['assigned_admin_id'] === (string) $admin['id'] ? ' selected' : '' ?>><?= $escape($admin['email']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn button button-primary" type="submit">Filter</button></div></div><a class="d-inline-block mt-3" href="<?= $root ?>">Clear filters</a></form><?php endif; ?>
<?php if ($rows === []): ?><section class="form-panel" data-empty-state><h2 class="h4">No training requests to show</h2><p><?= $staff ? 'Requests from schools will appear here. Try clearing your filters.' : 'Your submitted training requests and their progress will appear here.' ?></p></section><?php else: ?><div class="row g-3"><?php foreach (array_slice($rows, 0, 20) as $item): ?><div class="col-md-6"><article class="form-panel h-100"><p><span class="status-badge"><?= $escape(ucfirst(str_replace('_', ' ', $item['status']))) ?></span></p><h2 class="h4"><a href="<?= $root ?>?id=<?= (int) $item['id'] ?>"><?= $escape($item['reference']) ?></a></h2><?php if ($staff): ?><p><?= $escape($item['school_name']) ?></p><?php endif; ?><p><?= (int) $item['participants'] ?> participants · <?= $escape($item['location']) ?></p><p class="small mb-0">Submitted <?= $escape($data['wat']($item['created_at'])) ?> WAT</p></article></div><?php endforeach; ?></div><?php endif; ?>
<?php if (count($rows) > 20): ?><a class="btn button button-outline mt-4" href="<?= $escape($root . '?' . http_build_query($filters + ['before' => (int) $rows[19]['id']])) ?>">Older requests</a><?php endif; ?></div>
